head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

// 조회조건 결산일자

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // 결산일자 조회

    $c.frame.path("../frame_head").fn_SrchAcntclsDt();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_EqmtConstrSchd_OnLoadError
 * @description dts_EqmtConstrSchd 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_EqmtConstrSchd_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_EqmtConstrSchd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00212.dts_EqmtConstrSchd_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_EqmtConstrSchd_OnLoadCompleted
 * @description dts_EqmtConstrSchd 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_EqmtConstrSchd_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_EqmtConstrSchd.errorMsg) {
            alert(dts_EqmtConstrSchd.errorMsg);
        }

        // 그리드 타이틀 세팅.
        scwin.setGrdTitle();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00212.dts_EqmtConstrSchd_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 설비증설계획 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_EqmtConstrSchd",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_EqmtConstrSchd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_EqmtConstrSchd.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    // 필수항목 체크.

    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();

    scwin.vAcntclsDt = $c.frame.path("../frame_head").fn_GetAcntclsDt();
    if (scwin.vKisCd === "" || scwin.vAcntclsDt === "") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name setGrdTitle
 * @description 그리드 타이틀 세팅.
 * @returns {void}
 * @hidden N
 */
scwin.setGrdTitle = function() {
    $c.cm.setColumnProp(grd_EqmtConstrSchd, "PAYSCHD_AMT1", "Name", dts_EqmtConstrSchd.getCellData(0, "PAYSCHD_YY1") + "연도");
    $c.cm.setColumnProp(grd_EqmtConstrSchd, "PAYSCHD_AMT2", "Name", dts_EqmtConstrSchd.getCellData(0, "PAYSCHD_YY2") + "연도");
    $c.cm.setColumnProp(grd_EqmtConstrSchd, "PAYSCHD_AMT3", "Name", dts_EqmtConstrSchd.getCellData(0, "PAYSCHD_YY3") + "연도");
    $c.cm.setColumnProp(grd_EqmtConstrSchd, "PAYSCHD_AMT4", "Name", dts_EqmtConstrSchd.getCellData(0, "PAYSCHD_YY4") + "연도");
};

/**
 * @method
 * @name excelDownload
 * @description 엑셀파일다운로드
 * @returns {void}
 * @hidden N
 */
scwin.excelDownload = function() {
    if (dts_EqmtConstrSchd.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_EqmtConstrSchd, {fileName: "설비증설계획", type: "8"});
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    scwin.init();
};
